import {useEffect,useRef,useState} from 'react';
import {api,jsonText,parseObject,requestId} from '../api';
import {Agent,Json,Model,Provider,OrganizationLayout,roles} from '../types';
import {Field,Modal,Empty} from './UI';
import {SkillBindings} from './Skills';
import {RoleTemplatePicker,RoleTemplateSource} from './RoleTemplates';
import {GraphEditor,defaultGraph} from './Orchestration';
