type Kind='capability'|'routing'|'team'|'office'|'workflow'|'benchmark';
export type DesignAsset={id:string;kind:Kind;name:string;version:number;status:string;digest:string;config:Json;published_version?:number|null;source?:string;versions?:DesignAsset[];generation?:Json;created_at?:string;created_by?:string;published_by?:string;published_at?:string};
type Props={admin:boolean;models:Model[];providers:Provider[];agents:Agent[];organization?:OrganizationLayout|null;initialTab?:Kind|'hub';onRefresh:()=>Promise<void>;onModels:()=>void;onSkills:()=>void;onLaunch:(seed:Json)=>void;openAsset?:DesignAsset|null;onAssetOpened?:()=>void};
const kinds:Record<Kind,string>={capability:'能力画像',routing:'路由策略',team:'团队模板',office:'办公室布局',workflow:'工作流',benchmark:'评测套件'};
const dimensionLabels:Record<string,string>={coding:'代码能力',reasoning:'推理能力',tools:'工具调用',tool:'工具调用',latency:'响应速度',reliability:'可靠性',cost:'成本友好度',context:'上下文'};
const statusLabels:Record<string,string>={draft:'待审核草稿',published:'已批准发布',revoked:'已撤销'};
const roleTools:Record<string,string[]>={planner:['list_files','read_file','send_message','finish'],developer:['list_files','read_file','write_file','delete_file','run_command','send_message','finish'],tester:['list_files','read_file','write_file','delete_file','run_command','send_message','finish'],reviewer:['list_files','read_file','send_message','finish']};
const toolNames:Record<string,string>={list_files:'列出文件',read_file:'读取文件',write_file:'写入文件',delete_file:'删除文件',run_command:'沙箱执行命令',send_message:'发送消息',finish:'提交成果'};
const sourceLabel=(source?:string)=>({ai:'AI 建议',benchmark:'真实评测',manual:'人工配置',rules:'规则建议',rule_based:'规则建议',role_templates:'角色模板组合'}[source||'manual']||source);
const copy=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
const score=(n:unknown)=>typeof n==='number'&&Number.isFinite(n)?Math.round(n):null;
const isRecord=(value:unknown):value is Json=>!!value&&typeof value==='object'&&!Array.isArray(value);
function draftShapeProblem(kind:Kind,value:Json):string{
 if(!isRecord(value))return '配置必须是 JSON 对象';
 if(kind==='team'){
  if(value.members!==undefined&&!Array.isArray(value.members))return '成员列表必须是数组';
  for(const m of value.members||[]){
   if(!isRecord(m)||typeof m.key!=='string'||typeof m.name!=='string'||typeof m.role!=='string')return '每位成员需要文本标识、名称和角色';
   for(const key of ['fallback_model_ids','skills','tool_permissions'])if(m[key]!=null&&!Array.isArray(m[key]))return key+' 必须是数组';
   if(m.skills?.some((s:unknown)=>!isRecord(s)))return 'Skill 绑定必须是对象';
   if(m.communication!=null&&(!isRecord(m.communication)||m.communication.recipients!=null&&!Array.isArray(m.communication.recipients)))return '通信范围必须包含合法的成员数组';
   if(m.office_position!=null&&!isRecord(m.office_position))return '工位位置必须是对象';
  }
 }
 if(kind==='office'&&value.positions!=null&&(!isRecord(value.positions)||Object.values(value.positions).some(p=>!isRecord(p))))return '办公室位置必须是成员标识到位置对象的映射';
 if(kind==='office'&&value.floors!=null&&(!Array.isArray(value.floors)||value.floors.some((f:unknown)=>!isRecord(f)||!Array.isArray(f.zones)||f.zones.some((z:unknown)=>!isRecord(z)))))return '组织楼层与区域必须是对象数组';
 if(kind==='office'&&['teams','desks'].some(k=>value[k]!=null&&(!Array.isArray(value[k])||value[k].some((x:unknown)=>!isRecord(x)))))return '团队和办公桌必须是对象数组';
 if(kind==='office'&&value.teams?.some((t:Json)=>!Array.isArray(t.zone_ids)||!Array.isArray(t.member_ids)))return '团队功能区和员工名单必须是数组';
 if(kind==='benchmark'&&value.cases!==undefined&&(!Array.isArray(value.cases)||value.cases.some((c:unknown)=>!isRecord(c))))return '评测案例必须是对象数组';
 if(kind==='routing'&&(value.assignments!=null&&!isRecord(value.assignments)||value.rules!=null&&(!isRecord(value.rules)||value.rules.allowed_provider_ids!=null&&!Array.isArray(value.rules.allowed_provider_ids))))return '模型分配与企业规则需要对象配置';
 if(kind==='capability'&&['system_scores','overrides'].some(k=>value[k]!=null&&!isRecord(value[k])))return '评分与人工修正必须是对象';
 const graph=kind==='workflow'?value.graph:kind==='team'?value.workflow:null;
 if(graph!=null&&(!isRecord(graph)||graph.participants!=null&&!Array.isArray(graph.participants)||graph.criteria!=null&&(!Array.isArray(graph.criteria)||graph.criteria.some((c:unknown)=>!isRecord(c)))))return '工作流参与者和验收目标需要数组配置';
 return '';
}
function RawDraftEditor({value,onChange,disabled}:{value:Json;onChange:(v:Json)=>void;disabled:boolean}){const[text,setText]=useState(jsonText(value)),[error,setError]=useState('');return <Field label="修复草稿配置 · JSON" hint="原始草稿完整保留。修复结构后会恢复可视化编辑器；保存仍生成新版本。"><textarea className="code-input" rows={16} readOnly={disabled} value={text} onChange={e=>{setText(e.target.value);try{const config=parseObject(e.target.value);onChange(config);setError('');}catch(e){setError((e as Error).message);}}}/>{error&&<span className="form-error">{error}</span>}</Field>;}
function modelLabel(model:Model|undefined,providers:Provider[]){return model?`${providers.find(p=>p.id===model.provider_id)?.name||model.provider_id} / ${model.name} · ${model.model_id}`:'尚未绑定模型';}
function ModelSelect({value,onChange,models,providers,label='选择模型',optional=true,emptyLabel}:{value:string|null;onChange:(v:string)=>void;models:Model[];providers:Provider[];label?:string;optional?:boolean;emptyLabel?:string}){return <select aria-label={label} value={value||''} onChange={e=>onChange(e.target.value)}><option value="">{emptyLabel||(optional?'暂不绑定':'选择已配置模型')}</option>{models.map(m=><option key={m.id} value={m.id} disabled={m.enabled===false}>{modelLabel(m,providers)}{m.enabled===false?' · 已停用':''}</option>)}</select>;}
function Status({item}:{item:DesignAsset}){return <span className={'design-status '+item.status}><i/>{statusLabels[item.status]||item.status} · v{item.version}</span>;}
function startingConfig(kind:Kind,agents:Agent[]):Json{
 if(kind==='routing')return {task_type:'代码开发',assignments:{planner:null,developer:null,tester:null,reviewer:null},budget:'medium',max_parallel:3,rules:{allowed_provider_ids:[],allow_external:false,require_tools:true,max_model_calls:100}};
 if(kind==='team')return {members:[]};
 if(kind==='office')return departmentProposal(agents);
 if(kind==='workflow')return {graph:copy(defaultGraph),description:''};
 if(kind==='benchmark')return {cases:[{id:'case_1',dimension:'reasoning',prompt:'只输出 2+3 的结果，不要解释。',expected:'5',match:'exact'}]};
 return {model_profile_id:'',benchmark_id:null,system_scores:{},overrides:{},reason:''};
}

export default function DesignCenter(p:Props){
 const[tab,setTab]=useState<Kind|'hub'>(p.initialTab||'hub'),[assets,setAssets]=useState<DesignAsset[]>([]),[hub,setHub]=useState<Json>({models:[],benchmarks:[],dimensions:[]}),[loading,setLoading]=useState(true),[error,setError]=useState(''),[notice,setNotice]=useState('');
 const[focusFloor,setFocusFloor]=useState<number|undefined>();
 const[editor,setEditor]=useState<DesignAsset|null>(null),[editing,setEditing]=useState(false),[busy,setBusy]=useState(false),[history,setHistory]=useState<DesignAsset[]>([]),[expected,setExpected]=useState(0);
 const[recommendRequest,setRecommendRequest]=useState(''),[recommendModel,setRecommendModel]=useState(''),[budget,setBudget]=useState('medium'),[paidConsent,setPaidConsent]=useState(false),[benchmark,setBenchmark]=useState<Model|null>(null),[suite,setSuite]=useState(''),[benchmarkConsent,setBenchmarkConsent]=useState(false),[discovery,setDiscovery]=useState<Json|null>(null);
 const[comment,setComment]=useState(''),[reviewed,setReviewed]=useState(false),[modelHistory,setModelHistory]=useState<Json|null>(null),[enterprise,setEnterprise]=useState<Json>({ref:null}),[allowExternal,setAllowExternal]=useState(false);
 const operationKeys=useRef<Record<string,{signature:string;key:string}>>({});
 const operationHeader=(operation:string,body:Json)=>{const signature=JSON.stringify(body);if(operationKeys.current[operation]?.signature!==signature)operationKeys.current[operation]={signature,key:requestId()};return {'Idempotency-Key':operationKeys.current[operation].key};};
 const load=async()=>{setLoading(true);try{const[a,h,enterprise]=await Promise.all([api<DesignAsset[]>('/design/assets'),api<Json>('/model-hub'),api<Json>('/design/enterprise-policy')]);setAssets(a);setHub(h);setEnterprise(enterprise);setError('');}catch(e){setError((e as Error).message);}finally{setLoading(false);}};
 useEffect(()=>{void load();},[]);
 const transact=async(fn:()=>Promise<void>)=>{setBusy(true);setError('');try{await fn();}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
 const editCurrentOffice=(appendFloor=false)=>transact(async()=>{
  const current=await api<OrganizationLayout>('/organization');
  const latest=current.ref?await api<DesignAsset>('/design/assets/'+current.ref.id):null;
  const draft=prepareOrganizationDraft(current,latest,appendFloor);
  setEditor(draft.asset);setExpected(draft.expectedVersion);setHistory(draft.history);setFocusFloor(draft.focusFloor);setEditing(true);setReviewed(false);setComment('');
  setNotice((draft.pending?'已保留尚未发布的布局草稿。':'已复制当前应用布局。')+(appendFloor?'新楼层已加入编辑稿，默认包含必要公共配套。':'请调整楼层、部门、团队与功能区。')+'保存、发布并应用后才会改变办公室。');
 });
 const open=async(asset:DesignAsset,version?:number)=>{await transact(async()=>{const detail=await api<DesignAsset>('/design/assets/'+asset.id);const versioned=version&&version!==detail.version?await api<DesignAsset>(`/design/assets/${asset.id}/versions/${version}`):detail;setFocusFloor(undefined);setHistory(detail.versions||[detail]);setExpected(detail.version);setEditor(copy(versioned));setEditing(false);setReviewed(false);setComment('');});};
 const create=(kind:Kind,config?:Json,name='')=>{try{setFocusFloor(undefined);setEditor({id:'',kind,name,version:0,status:'draft',digest:'',source:'manual',config:config||startingConfig(kind,p.agents)});setEditing(true);setExpected(0);setHistory([]);setReviewed(false);setError('');}catch(e){setError((e as Error).message);}};
 const save=()=>transact(async()=>{if(!editor?.name.trim())throw Error('请填写配置名称');const result=await api<DesignAsset>('/design/assets'+(editor.id?'/'+editor.id:''),editor.id?'PUT':'POST',{...(editor.id?{expected_version:expected}:{kind:editor.kind}),name:editor.name,config:editor.config,source:'manual'});await load();setEditor(result);setHistory([result,...history]);setExpected(result.version);setEditing(false);setReviewed(false);setNotice('已保存新草稿。请核对内容并批准发布，才可供新任务使用。');});
 const review=(action:'publish'|'revoke')=>transact(async()=>{if(!editor||!reviewed)throw Error('请先确认已核对当前版本');const result=await api<DesignAsset>(`/design/assets/${editor.id}/${action}`,'POST',{version:editor.version,digest:editor.digest,comment});setEditor(result);setHistory(h=>h.map(v=>v.version===result.version?result:v));setReviewed(false);await load();setNotice(action==='publish'?'该版本已批准发布。后续编辑会创建独立草稿。':'该版本已撤销，不再用于新运行。');});
 const generate=()=>transact(async()=>{if(recommendRequest.trim().length<3)throw Error('请描述任务需求');const body={kind:tab,request:recommendRequest,model_profile_id:recommendModel||null,budget,allow_external:allowExternal,acknowledge:!!recommendModel&&paidConsent};const r=await api<DesignAsset>('/design/recommend','POST',body,operationHeader('recommend',body));delete operationKeys.current.recommend;await load();const asset=(r as any).asset||r;setEditor(asset);setExpected(asset.version);setHistory([asset]);setEditing(true);setNotice(recommendModel?'AI 方案已生成，请编辑并审核。':'已生成规则建议；未调用 AI。请补充业务判断后审核。');});
 useEffect(()=>{const asset=p.openAsset;if(!asset)return;setTab(asset.kind==='capability'?'hub':asset.kind);setEditor(copy(asset));setExpected(asset.version);setHistory(asset.versions||[asset]);setEditing(p.admin);setReviewed(false);setComment('');setNotice('角色方案已保存为未发布草稿。请确认模型、权限与 Skill 后再发布。');p.onAssetOpened?.();void load();},[p.openAsset?.id,p.openAsset?.version]);
 const patch=(c:Json)=>setEditor(a=>a?{...a,config:{...a.config,...c}}:a);
 const shown=assets.filter(a=>a.kind===tab);
 const shapeProblem=editor?draftShapeProblem(editor.kind,editor.config):'';
 return <div className="design-center" data-testid="design-center">
  <nav className="design-tabs" aria-label="设计中心分类">{([['hub','Model Hub'],['routing','模型路由'],['team','团队设计'],['office','办公室'],['benchmark','Benchmark']] as const).map(([id,label])=><button className={tab===id?'active':''} key={id} onClick={()=>{setTab(id);setError('');}}>{label}{id!=='hub'&&<small>{assets.filter(a=>a.kind===id).length}</small>}</button>)}<button aria-label="刷新设计中心" disabled={loading} onClick={()=>void load()}><RefreshCw size={15}/></button></nav>
  {error&&!editor&&!benchmark&&<div role="alert" className="form-error">{error}</div>}{notice&&<div className="design-notice" role="status"><ShieldCheck size={16}/><span>{notice}</span><button aria-label="关闭提示" onClick={()=>setNotice('')}>×</button></div>}
  {enterprise.ref&&<div className="design-enterprise"><ShieldCheck size={16}/><span>企业规则：{assets.find(a=>a.id===enterprise.ref.id)?.name||enterprise.ref.id} · v{enterprise.ref.version}<small>所有新任务均受此规则约束，任务级模型覆盖仍需校验。</small></span>{p.admin&&<button className="text-button" disabled={busy} onClick={()=>void transact(async()=>{setEnterprise(await api('/design/enterprise-policy','PUT',{ref:null}));setNotice('已停止全局应用企业规则；已创建运行保留原快照。');})}>停用全局规则</button>}</div>}
  {loading&&!assets.length&&!hub.models?.length&&<p className="microcopy">正在读取模型资产与版本…</p>}
  {tab==='hub'?<>
   <div className="design-heading"><div><h3>模型资产与能力画像</h3><p>系统实测 + 管理员修正。无评测显示未知，推荐只使用已发布画像。</p></div><button className="button secondary" onClick={p.onModels}><Network size={15}/>供应商与协议配置</button></div>
   <div className="hub-stats"><div><b>{p.providers.length}</b><span>供应商</span></div><div><b>{p.models.length}</b><span>模型资产</span></div><div><b>{assets.filter(a=>a.kind==='capability'&&a.published_version).length}</b><span>已发布画像</span></div><div><b>{hub.benchmarks?.length||0}</b><span>真实评测记录</span></div></div>
   <div className="hub-models">{p.models.map(model=>{const h=(hub.models||[]).find((m:Json)=>m.id===model.id)||{};const profiles=assets.filter(a=>a.kind==='capability'&&a.config.model_profile_id===model.id);const profile=profiles[0];const cap=h.capability;const effective=cap?.effective_scores||cap?.final_scores||{};return <article className="hub-model" key={model.id}><header><span className="design-model-icon"><Network size={20}/></span><div><small>{p.providers.find(x=>x.id===model.provider_id)?.name}</small><h3>{model.name}</h3><code>{model.model_id}</code></div><span className={'design-status '+(profile?.published_version?'published':'draft')}>{profile?.published_version?'画像 v'+profile.published_version:'画像待确认'}</span></header><div className="hub-score-grid">{['coding','reasoning','tool','latency','reliability','cost'].map(d=>{const n=score(effective[d]);return <div key={d}><label>{dimensionLabels[d]}<b>{n===null?'未知':n}</b></label><span className={'score-track '+(n===null?'unknown':'')}><i style={{width:(n??0)+'%'}}/></span></div>;})}</div><p className="microcopy">{model.supports_tools?'声明支持工具':'未声明工具支持'} · {h.capability?(h.capability.stale?'画像已过期，请重新评测':'能力分来自已发布画像'):'尚无已发布评分'}{profile&&profile.version!==profile.published_version?' · 存在未发布变更':''}</p><footer>{p.admin&&<button className="button secondary small" onClick={()=>{if(profile)void open(profile);else create('capability',{...startingConfig('capability',[]),model_profile_id:model.id},model.name+' · 能力画像');}}>人工调整画像</button>}<button className="text-button" onClick={()=>void transact(async()=>setModelHistory(await api(`/model-hub/models/${model.id}/history`)))}>评测记录</button>{p.admin&&<button className="text-button" onClick={()=>{setBenchmark(model);setBenchmarkConsent(false);setSuite('');setError('');}}>运行评测</button>}</footer></article>;})}</div>
   {!p.models.length&&<Empty title="从第一个模型资产开始" description="连接供应商，登记模型与协议。能力测评和人工修正会保存为待审核画像。" action={<button className="button primary" onClick={p.onModels}>配置供应商与模型</button>}/>}
   {p.providers.length>0&&<section className="design-discovery"><div><h3>发现模型，只形成候选列表</h3><p>发现结果需人工登记，且不会自动为 Agent 改绑。</p></div>{p.providers.filter(x=>x.enabled).map(provider=><button key={provider.id} className="button secondary small" disabled={!p.admin||busy} onClick={()=>void transact(async()=>setDiscovery({provider:provider.name,...await api(`/model-hub/providers/${provider.id}/discover`,'POST',{})}))}>{provider.name} · 发现模型</button>)}</section>}
   {assets.filter(a=>a.kind==='capability').length>0&&<AssetCards assets={assets.filter(a=>a.kind==='capability')} onOpen={open}/>}
  </>:<>
   <div className="design-heading"><h3>{kinds[tab]}</h3>{p.admin&&<div className="inline-actions">{tab==='office'&&<><button className="button secondary" disabled={busy} onClick={()=>void editCurrentOffice()}>编辑当前楼层与团队</button><button className="button primary" disabled={busy} onClick={()=>void editCurrentOffice(true)}><Plus size={15}/>新增楼层／部门</button></>}<button className={tab==='office'?'button secondary':'button primary'} onClick={()=>create(tab)}><Plus size={15}/>{tab==='office'?'新建独立布局方案':'新建'+kinds[tab]}</button></div>}</div>
   {(tab==='routing'||tab==='team')&&p.admin&&<section className="design-recommend"><div><span className="eyebrow">{recommendModel?'AI DESIGN ASSISTANT':'RULE-BASED SUGGESTION'}</span><h3>{tab==='team'?'描述需求，生成可编辑团队方案':'描述任务，推荐各阶段的模型'}</h3><p>{recommendModel?'使用选定模型生成草稿，你可以逐项修改。':'默认使用已发布画像与规则生成建议，不产生模型调用。'}</p></div><Field label="任务与团队目标"><textarea aria-label="推荐需求" rows={3} value={recommendRequest} onChange={e=>setRecommendRequest(e.target.value)} placeholder={tab==='team'?'例如：开发商城系统，需要后端、前端、测试及安全审查。':'例如：修复支付模块，优先保证正确性，控制外部模型使用。'}/></Field><div className="form-grid"><Field label="建议生成方式"><ModelSelect value={recommendModel} onChange={v=>{setRecommendModel(v);setPaidConsent(false);}} models={p.models} providers={p.providers} label="建议生成模型" emptyLabel="本地规则建议 · 不调用 AI"/></Field><Field label="预算偏好"><select value={budget} onChange={e=>setBudget(e.target.value)}><option value="low">低 · 关注成本</option><option value="medium">中 · 均衡</option><option value="high">高 · 关注能力</option></select></Field></div><label className="check"><input type="checkbox" checked={allowExternal} onChange={e=>setAllowExternal(e.target.checked)}/>允许推荐外部模型，并将需求发送给外部设计助手（若选用）</label>{recommendModel&&<label className="check"><input type="checkbox" checked={paidConsent} onChange={e=>setPaidConsent(e.target.checked)}/>我同意将上述需求发送给选定模型，产生一次实际模型调用费用。</label>}<button className="button primary" disabled={busy||!recommendRequest.trim()||!!recommendModel&&!paidConsent} onClick={()=>void generate()}>{busy?'正在生成…':recommendModel?'AI 生成草稿方案':'生成规则建议草稿'}<ArrowRight size={15}/></button></section>}
   {tab==='office'&&<section className="organization-overview"><div className="organization-floor-cards">{(p.organization?.config.floors||[]).map(f=><article key={f.floor}><span>{f.floor}F</span><div><b>{f.department}</b><small>{f.name} · {(p.organization?.config.teams||[]).filter(t=>t.floor===f.floor).length} 个团队 · {f.zones.length} 个区域</small></div></article>)}</div></section>}
   {tab==='benchmark'&&<p className="design-context">建立符合内部业务的评分案例。样例只验证有界的指令遵循，不能代表模型的通用能力；请维护真实案例并保存评测版本。</p>}
   <AssetCards assets={shown} onOpen={open}/>{!shown.length&&!loading&&<Empty title={'还没有'+kinds[tab]} description="从人工配置或建议草稿开始，审核后发布为可复用的组织资产。"/>}
  </>}

  {editor&&<Modal title={kinds[editor.kind]+' · '+(editor.id?'版本管理':'新建设计')} wide onClose={()=>{if(!busy){setEditor(null);setError('');}}}><form className="modal-content design-editor" onSubmit={e=>{e.preventDefault();void save();}}>
   <div className="design-editor-meta"><Status item={editor}/><span>{sourceLabel(editor.source)}</span>{editor.id&&<select aria-label="配置历史版本" disabled={busy||editing} value={editor.version} onChange={e=>void open(editor,Number(e.target.value))}>{history.map(v=><option key={v.version} value={v.version}>v{v.version} · {statusLabels[v.status]}</option>)}</select>}<span className="design-mode">{editing?'DESIGN · 编辑态':'REVIEW · 审核态'}</span></div>
   {!editing&&notice&&<p className="design-notice" role="status">{notice}</p>}
   {editor.digest&&<p className="design-digest" title={editor.digest}>内容摘要 · {editor.digest.slice(0,24)}…　{editor.created_at?new Date(editor.created_at).toLocaleString():''}</p>}
   {editor.generation?.method&&<section className="design-rationale"><h3>{editor.generation.method==='ai'?'AI 设计建议':editor.generation.method==='benchmark'?'真实 Benchmark · 已产生模型调用':editor.generation.method==='role_templates'?'角色模板组合 · 未调用 AI':'本地规则建议 · 未调用 AI'}</h3><p>{editor.generation.reason}</p>{editor.generation.reasons?.map((r:Json,i:number)=><p key={i}>{roles[r.role]||r.role}：{modelLabel(p.models.find(m=>m.id===r.model_id),p.providers)} · {r.reason}</p>)}{editor.generation.skill_suggestions?.length>0&&<details><summary>候选 Skill · 需要独立审核与绑定</summary>{editor.generation.skill_suggestions.map((s:Json)=><p key={s.skill_id}>{s.name} · v{s.version} · {s.status==='approved'?'已审核，可手动绑定':'尚需管理员审核'}</p>)}</details>}</section>}
   {(editor.config.recommendation||editor.config.rationale||editor.config.reasons)&&<details open className="design-rationale"><summary>建议来源与推荐理由</summary><pre>{typeof editor.config.rationale==='string'?editor.config.rationale:jsonText(editor.config.recommendation||editor.config.reasons||editor.config.rationale)}</pre></details>}
   {shapeProblem&&<><p role="alert" className="form-error">此草稿结构尚未完整：{shapeProblem}。请修复后再发布。</p><RawDraftEditor key={editor.id+':'+editor.version} value={editor.config} disabled={!editing||busy} onChange={config=>setEditor({...editor,config})}/></>}
   <fieldset disabled={busy}><Field label="配置名称"><input aria-label="设计配置名称" readOnly={!editing} required value={editor.name} onChange={e=>setEditor({...editor,name:e.target.value})}/></Field>
   {!shapeProblem&&<>
    {editor.kind==='capability'&&<fieldset disabled={!editing}><CapabilityEditor value={editor.config} onChange={patch} models={p.models} providers={p.providers} dimensions={Array.isArray(hub.dimensions)?hub.dimensions.map((d:any)=>typeof d==='string'?d:d.id||d.key):Object.keys(hub.dimensions||{})}/></fieldset>}
    {editor.kind==='routing'&&<fieldset disabled={!editing}><RoutingEditor value={editor.config} onChange={patch} models={p.models} providers={p.providers}/></fieldset>}
    {editor.kind==='team'&&<TeamEditor value={editor.config} onChange={patch} models={p.models} providers={p.providers} readOnly={!editing} onSkills={p.onSkills}/>}
    {editor.kind==='office'&&<OrganizationDesigner key={editor.id+':'+editor.version+':'+focusFloor} initialFloor={focusFloor} value={editor.config} onChange={patch} agents={p.agents} readOnly={!editing} legacy={<OfficeEditor value={editor.config} onChange={patch} agents={p.agents} readOnly={!editing} organization/>}/>}
    {editor.kind==='workflow'&&<fieldset disabled={!editing}><><Field label="工作流说明"><textarea value={editor.config.description||''} onChange={e=>patch({description:e.target.value})}/></Field><GraphEditor value={editor.config.graph||defaultGraph} onChange={graph=>patch({graph})} agents={p.agents}/></></fieldset>}
    {editor.kind==='benchmark'&&<fieldset disabled={!editing}><BenchmarkEditor value={editor.config} onChange={patch}/></fieldset>}
   </>}
   </fieldset>
   {error&&<p role="alert" className="form-error">{error}</p>}
   {!editing&&editor.id&&<details className="design-audit"><summary>完整配置与审计信息</summary><pre className="json-view">{jsonText({config:editor.config,created_by:editor.created_by,published_by:editor.published_by,published_at:editor.published_at,digest:editor.digest})}</pre></details>}
   {p.admin&&<footer className="design-editor-actions">{editing?<><p>保存会创建新草稿版本，审核发布后才可执行。</p><button className="button primary" disabled={busy} type="submit">{busy?'保存中…':'保存草稿版本'}</button></>:<><button type="button" className="button secondary" disabled={busy} onClick={()=>{setEditing(true);setReviewed(false);}}>编辑并创建新版本</button><div className="design-review"><Field label="审核说明"><textarea rows={2} value={comment} onChange={e=>setComment(e.target.value)} placeholder="记录人工修正、发布依据或撤销原因"/></Field><label className="check"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/>{editor.kind==='office'?'我已核对部门、楼层、区域与工位；理解部门调整会影响后续运行的同部门通信对象，既有任务和工具权限不变':'我已核对此版本的模型、权限、Skill 与配置内容'}</label><button type="button" className={'button '+(editor.status==='published'?'danger':'primary')} disabled={busy||!reviewed||editor.status==='revoked'} onClick={()=>void review(editor.status==='published'?'revoke':'publish')}>{editor.status==='published'?'撤销此发布版本':editor.status==='revoked'?'此版本已撤销':'批准并发布此版本'}</button></div>{editor.kind==='routing'&&editor.status==='published'&&<button type="button" className="button secondary" disabled={busy} onClick={()=>void transact(async()=>{const result=await api('/design/enterprise-policy','PUT',{ref:{id:editor.id,version:editor.version}});setEnterprise(result);setNotice('此已发布策略的企业规则已启用，将约束所有新任务。');})}>设为所有新任务的企业规则</button>}{editor.kind==='office'&&editor.status==='published'&&<button type="button" className="button secondary" disabled={busy||!reviewed} onClick={()=>void transact(async()=>{await api(`/design/assets/${editor.id}/apply-office`,'POST',{version:editor.version,digest:editor.digest,comment});await p.onRefresh();setReviewed(false);setNotice('已应用明确版本的组织布局：只调整所列成员的部门和工位，模型、工具、通信策略与已创建任务未改变。');})}>应用办公室布局</button>}{editor.kind==='team'&&editor.status==='published'&&<button type="button" className="button secondary" disabled={busy} onClick={()=>void transact(async()=>{const result=await api(`/design/assets/${editor.id}/instantiate`,'POST',{version:editor.version,digest:editor.digest});await p.onRefresh();setEditor(null);setNotice('团队实例已创建，成员使用此模板的确定版本。请确认任务内容后再发起运行。');p.onLaunch({execution_strategy:'autonomous',run_project_checks:false,agent_ids:result.agent_ids});})}>实例化团队并填写任务 →</button>}</>}</footer>}
  </form></Modal>}

  {benchmark&&<Modal title={'真实评测 · '+benchmark.name} onClose={()=>{if(!busy){setBenchmark(null);setError('');}}}><div className="modal-content"><p className="design-context">评测会向供应商发送测试请求并产生费用。结果记录模型版本、耗时与证据，评分只保存为待审核画像。</p><Field label="评测套件"><select aria-label="评测套件" value={suite} onChange={e=>setSuite(e.target.value)}><option value="">内置基础检查（有限样例）</option>{assets.filter(a=>a.kind==='benchmark'&&a.published_version).map(a=><option key={a.id} value={a.id+':'+a.published_version}>{a.name} · 已发布 v{a.published_version}</option>)}</select></Field><label className="check"><input type="checkbox" checked={benchmarkConsent} onChange={e=>setBenchmarkConsent(e.target.checked)}/>确认调用此模型进行评测，并承担相应 API 费用。</label>{error&&<p className="form-error">{error}</p>}<button className="button primary" disabled={busy||!benchmarkConsent} onClick={()=>void transact(async()=>{const parts=suite.split(':');const body={acknowledge:true,...(suite?{suite_ref:{id:parts[0],version:Number(parts[1])}}:{})};const result=await api(`/model-hub/models/${benchmark.id}/benchmark`,'POST',body,operationHeader('benchmark:'+benchmark.id,body));delete operationKeys.current['benchmark:'+benchmark.id];await load();setBenchmark(null);setNotice('评测完成，结果已记录。请查看并审核能力画像草稿。');setModelHistory(result);})}>{busy?'评测进行中…':'运行评测并保存证据'}</button></div></Modal>}
  {modelHistory&&<Modal title="模型评测证据" wide onClose={()=>setModelHistory(null)}><div className="modal-content"><p className="microcopy">真实测量只反映当前案例、供应商与环境。未测试的维度保持未知。</p><pre className="json-view">{jsonText(modelHistory)}</pre></div></Modal>}
  {discovery&&<Modal title={'模型发现 · '+discovery.provider} onClose={()=>setDiscovery(null)}><div className="modal-content"><p className="microcopy">以下仅为发现结果。登记模型时仍需确认名称、参数和支持的能力。</p><pre className="json-view">{jsonText(discovery.candidates||discovery.models||discovery)}</pre><button className="button secondary" onClick={()=>{setDiscovery(null);p.onModels();}}>前往供应商与模型登记</button></div></Modal>}
 </div>;
}

function AssetCards({assets,onOpen}:{assets:DesignAsset[];onOpen:(a:DesignAsset)=>void}){return <div className="design-asset-grid">{assets.map(a=><article key={a.id} className="design-asset"><header><span className="design-kind">{kinds[a.kind]}</span><Status item={a}/></header><h3>{a.name}</h3><p>{a.kind==='team'?`${a.config.members?.length||0} 位成员 · 独立模型与权限`:a.kind==='routing'?`${a.config.task_type||'通用任务'} · ${a.config.max_parallel||3} 并发`:a.kind==='office'?Array.isArray(a.config.desks)?`${a.config.floors?.length||0} 层 · ${a.config.teams?.length||0} 团队 · ${a.config.desks.length} 张桌 · ${Object.keys(a.config.positions||{}).length} 员工`:`${Object.keys(a.config.positions||{}).length} 个成员位置`:a.kind==='benchmark'?`${a.config.cases?.length||0} 项评测案例`:a.kind==='capability'?`${Object.keys(a.config.overrides||{}).length} 项人工修正`:'目标、流程与验收'}</p><footer><small>{a.published_version?'可用 v'+a.published_version:'尚未发布'} · {sourceLabel(a.source)}</small><button className="text-button" onClick={()=>onOpen(a)}>查看 / 编辑 <ArrowRight size={13}/></button></footer></article>)}</div>;}

function CapabilityEditor({value,onChange,models,providers,dimensions}:{value:Json;onChange:(c:Json)=>void;models:Model[];providers:Provider[];dimensions:string[]}){
 const dims=Array.from(new Set([...['coding','reasoning','tool','latency','reliability','cost'],...dimensions,...Object.keys(value.system_scores||{}),...Object.keys(value.overrides||{})])).filter(Boolean);
 return <><Field label="关联模型"><ModelSelect value={value.model_profile_id} models={models} providers={providers} onChange={model_profile_id=>onChange({model_profile_id})}/></Field><div className="design-context">系统评分来自实际 Benchmark，不能手动修改。管理员调整是最终分值覆盖；留空继承系统分，没有证据时保持未知。</div><div className="capability-table"><header><span>能力维度</span><span>系统评分</span><span>管理员调整</span><span>最终画像</span></header>{dims.map(d=>{const base=score(value.system_scores?.[d]),override=score(value.overrides?.[d]);return <div key={d}><b>{dimensionLabels[d]||d}</b><span>{base??'未知'}</span><input aria-label={d+' 管理员调整'} type="number" min={0} max={100} step={1} value={value.overrides?.[d]??''} placeholder="继承" onChange={e=>{const overrides={...value.overrides};if(e.target.value==='')delete overrides[d];else overrides[d]=Number(e.target.value);onChange({overrides});}}/><strong>{override??base??'未知'}</strong></div>;})}</div><Field label="人工调整依据" hint="记录与企业项目、模型成本或内部语言相关的判断依据。"><textarea aria-label="人工调整依据" rows={3} value={value.reason||''} onChange={e=>onChange({reason:e.target.value})}/></Field>{value.benchmark_id&&<p className="microcopy">评测证据：{value.benchmark_id}</p>}</>;
}

function RoutingEditor({value,onChange,models,providers}:{value:Json;onChange:(v:Json)=>void;models:Model[];providers:Provider[]}){const rules=value.rules||{};const setRules=(p:Json)=>onChange({rules:{...rules,...p}});return <><div className="form-grid"><Field label="任务类型"><input value={value.task_type||''} onChange={e=>onChange({task_type:e.target.value})}/></Field><Field label="预算偏好"><select value={value.budget||'medium'} onChange={e=>onChange({budget:e.target.value})}><option value="low">低</option><option value="medium">中</option><option value="high">高</option></select></Field></div><div className="routing-stage-grid">{Object.entries(roles).map(([role,label],i)=><article key={role}><span>0{i+1} · {label}</span><ModelSelect label={label+'路由模型'} value={value.assignments?.[role]} models={models} providers={providers} onChange={id=>onChange({assignments:{...value.assignments,[role]:id||null}})}/></article>)}</div><div className="form-grid"><Field label="最大并发"><input type="number" min={1} max={32} value={value.max_parallel??3} onChange={e=>onChange({max_parallel:Number(e.target.value)})}/></Field><Field label="单运行模型调用上限"><input type="number" min={1} max={10000} value={rules.max_model_calls??100} onChange={e=>setRules({max_model_calls:Number(e.target.value)})}/></Field></div><section className="design-rules"><h3>企业使用规则</h3><label className="check"><input type="checkbox" checked={rules.allow_external===true} onChange={e=>setRules({allow_external:e.target.checked})}/>策略允许外部模型（仍需项目授权）</label><label className="check"><input type="checkbox" checked={rules.require_tools!==false} onChange={e=>setRules({require_tools:e.target.checked})}/>只允许支持工具调用的模型</label><Field label="允许的供应商" hint="不勾选表示不增加供应商名单限制；停用与项目外发权限仍生效。"><div className="design-check-grid">{providers.map(provider=><label key={provider.id} className="check"><input type="checkbox" checked={(rules.allowed_provider_ids||[]).includes(provider.id)} onChange={e=>setRules({allowed_provider_ids:e.target.checked?[...(rules.allowed_provider_ids||[]),provider.id]:(rules.allowed_provider_ids||[]).filter((id:string)=>id!==provider.id)})}/>{provider.name}</label>)}</div></Field></section></>;}

function TeamEditor({value,onChange,models,providers,readOnly,onSkills}:{value:Json;onChange:(c:Json)=>void;models:Model[];providers:Provider[];readOnly:boolean;onSkills:()=>void}){
 const members:Json[]=value.members||[];const[picker,setPicker]=useState(false);const[selected,setSelected]=useState(members[0]?.key||'');const member=members.find(m=>m.key===selected)||members[0];const patch=(p:Json)=>onChange({members:members.map(m=>m.key===member?.key?{...m,...p}:m)});
 const add=()=>{const key='member_'+requestId().slice(0,8);onChange({members:[...members,{key,name:'新成员',role:'developer',model_profile_id:null,fallback_model_ids:[],instructions:'',department:'',reports_to:members.find(m=>m.role==='planner')?.key||null,communication:{scope:'run',recipients:[]},skills:[],tool_permissions:roleTools.developer,office_position:{x:0,z:0,floor:1,zone:'协作区'}}]});setSelected(key);};
 const remove=()=>{if(!member)return;onChange({members:members.filter(m=>m.key!==member.key).map(m=>({...m,reports_to:m.reports_to===member.key?null:m.reports_to,communication:{...m.communication,recipients:(m.communication?.recipients||[]).filter((k:string)=>k!==member.key)}}))});setSelected('');};
 return <><div className="team-organization"><header><div><h3>团队组织图</h3><p>点击成员编辑；上下级关系不扩大工具权限。</p></div><div className="inline-actions"><button className="button secondary small" type="button" disabled={readOnly} onClick={()=>setPicker(true)}><Users size={14}/>从角色模板库添加</button><button className="button secondary small" type="button" disabled={readOnly} onClick={add}><Plus size={14}/>增加成员</button></div></header><div className="team-chart">{members.filter(m=>!m.reports_to||!members.some(x=>x.key===m.reports_to)).map(root=><div className="team-branch" key={root.key}><TeamNode member={root} selected={member?.key} choose={setSelected} models={models} providers={providers}/><div className="team-children">{members.filter(m=>m.reports_to===root.key).map(child=><div key={child.key}><TeamNode member={child} selected={member?.key} choose={setSelected} models={models} providers={providers}/>{members.filter(m=>m.reports_to===child.key).map(nested=><TeamNode key={nested.key} member={nested} selected={member?.key} choose={setSelected} models={models} providers={providers}/>)}</div>)}</div></div>)}</div>{!members.length&&<p className="microcopy">添加成员，或通过需求生成团队建议草稿。</p>}</div>
  {members.length>0&&<div className="team-editor-selection"><Field label="当前编辑成员"><select value={member?.key||''} onChange={e=>setSelected(e.target.value)}>{members.map(m=><option key={m.key} value={m.key}>{m.name} · {roles[m.role]||m.role}</option>)}</select></Field><button className="text-button danger-text" type="button" disabled={readOnly} onClick={remove}>从草稿移除此成员</button></div>}
  {member?.role_template_ref&&<RoleTemplateSource key={member.key} reference={member.role_template_ref}/>}
  {member&&<Field label="业务岗位名称" hint="例如市场策划、产品经理、财务分析；岗位描述不扩大执行权限。"><input aria-label="团队成员业务岗位" disabled={readOnly} maxLength={120} value={member.job_title||''} placeholder="填写实际业务岗位" onChange={e=>patch({job_title:e.target.value})}/></Field>}
  {member&&<fieldset className="team-member-editor" disabled={readOnly}><div className="form-grid"><Field label="成员名称"><input required value={member.name} onChange={e=>patch({name:e.target.value})}/></Field><Field label="职责角色"><select value={member.role} onChange={e=>patch({role:e.target.value,tool_permissions:roleTools[e.target.value]})}>{Object.entries(roles).map(([key,label])=><option value={key} key={key}>{label}</option>)}</select></Field></div><div className="form-grid"><Field label="主模型"><ModelSelect value={member.model_profile_id} models={models} providers={providers} onChange={id=>patch({model_profile_id:id||null})}/></Field><Field label="直属领导"><select value={member.reports_to||''} onChange={e=>patch({reports_to:e.target.value||null})}><option value="">无上级</option>{members.filter(m=>m.key!==member.key).map(m=><option value={m.key} key={m.key}>{m.name}</option>)}</select></Field></div><Field label="备用模型"><select multiple value={member.fallback_model_ids||[]} onChange={e=>patch({fallback_model_ids:Array.from(e.target.selectedOptions).map(o=>o.value)})}>{models.filter(m=>m.id!==member.model_profile_id).map(m=><option key={m.id} value={m.id}>{modelLabel(m,providers)}</option>)}</select></Field><Field label="职责与交付要求"><textarea rows={3} value={member.instructions||''} onChange={e=>patch({instructions:e.target.value})}/></Field><div className="form-grid"><Field label="部门"><input value={member.department||''} onChange={e=>patch({department:e.target.value})}/></Field><Field label="通信范围"><select value={member.communication?.scope||'run'} onChange={e=>patch({communication:{...member.communication,scope:e.target.value,recipients:member.communication?.recipients||[]}})}><option value="run">本次运行的成员</option><option value="department">同部门</option><option value="reporting">汇报关系</option><option value="custom">指定成员</option></select></Field></div>{member.communication?.scope==='custom'&&<Field label="允许通信的成员"><select multiple value={member.communication.recipients||[]} onChange={e=>patch({communication:{...member.communication,recipients:Array.from(e.target.selectedOptions).map(o=>o.value)}})}>{members.filter(m=>m.key!==member.key).map(m=><option key={m.key} value={m.key}>{m.name}</option>)}</select></Field>}<Field label="项目级工具权限" hint="只能收缩当前角色的工具范围；Skill 不能扩大权限。"><div className="design-check-grid">{(roleTools[member.role]||[]).map(tool=><label className="check" key={tool}><input type="checkbox" checked={(member.tool_permissions||roleTools[member.role]||[]).includes(tool)} onChange={e=>patch({tool_permissions:e.target.checked?[...(member.tool_permissions||roleTools[member.role]||[]),tool]:(member.tool_permissions||roleTools[member.role]||[]).filter((t:string)=>t!==tool)})}/>{toolNames[tool]||tool}</label>)}</div></Field><SkillBindings key={member.key} value={member.skills||[]} onChange={skills=>patch({skills})}/><p className="microcopy">如需新 Skill，请先在能力库中查看内容、权限与版本，审核后再返回绑定。</p></fieldset>}
  {picker&&!readOnly&&<RoleTemplatePicker onClose={()=>setPicker(false)} onMember={proposal=>{const key=members.some(m=>m.key===proposal.key)?'member_'+requestId().slice(0,8):proposal.key;onChange({members:[...members,{...proposal,key}]});setSelected(key);setPicker(false);}}/>}
  {members.length>0&&<OfficeEditor value={{positions:Object.fromEntries(members.map(m=>[m.key,m.office_position||{x:0,z:0,floor:1,zone:'协作区'}]))}} onChange={v=>onChange({members:members.map(m=>({...m,office_position:v.positions[m.key]}))})} agents={members.map(m=>({...m,id:m.key})) as Agent[]} readOnly={readOnly}/>}
 </>;
}
function TeamNode({member,selected,choose,models,providers}:{member:Json;selected:string;choose:(v:string)=>void;models:Model[];providers:Provider[]}){return <button type="button" className={'team-node '+(selected===member.key?'selected':'')} onClick={()=>choose(member.key)}><span>{member.name?.slice(0,1)||'A'}</span><b>{member.name}</b><small>{member.job_title||roles[member.role]||member.role}</small><em>{modelLabel(models.find(m=>m.id===member.model_profile_id),providers)}</em></button>;}

const organizationColors=['#7296ab','#83a184','#bd9d75','#a18bb8','#ae8393','#72a5a5'];
const zoneKinds:Record<string,string>={work:'工作区',meeting:'会议区',common:'公共区'};
const zoneContains=(zone:Json,x:number,z:number)=>x-1.4>=zone.x-zone.width/2-1e-9&&x+1.4<=zone.x+zone.width/2+1e-9&&z-.6>=zone.z-zone.depth/2-1e-9&&z+1.45<=zone.z+zone.depth/2+1e-9;
const seatsOverlap=(a:Json,b:Json)=>a.floor===b.floor&&Math.abs(a.x-b.x)<2.8-1e-9&&Math.abs(a.z-b.z)<2.05-1e-9;
function suggestedFloor(floor:number,department:string,dense=false):Json{
 const color=organizationColors[(floor-1)%organizationColors.length];
 return {floor,name:`${floor} 楼 · ${department}`,department,zones:dense?
  [{id:`floor_${floor}_work`,name:'部门工作区',kind:'work',x:0,z:0,width:24,depth:16,color}]:
  [{id:`floor_${floor}_work`,name:'部门工作区',kind:'work',x:0,z:-2,width:22,depth:10,color},
   {id:`floor_${floor}_meeting`,name:'讨论会议区',kind:'meeting',x:5.75,z:5.5,width:10.5,depth:3,color:'#9a96b3'},
   {id:`floor_${floor}_common`,name:'公共休息区',kind:'common',x:-5.75,z:5.5,width:10.5,depth:3,color:'#8dab9d'}]};
}
function freeSeat(zone:Json,floor:number,positions:Record<string,Json>,except=''):Json|null{
 for(let z=zone.z-zone.depth/2+.7;z<=zone.z+zone.depth/2-1.45+1e-9;z+=2.5){
  for(let x=zone.x-zone.width/2+1.5;x<=zone.x+zone.width/2-1.4+1e-9;x+=3.1){
   const position={x:Math.round(x*100)/100,z:Math.round(z*100)/100,floor,zone:zone.id};
   if(zoneContains(zone,position.x,position.z)&&!Object.entries(positions).some(([id,p])=>id!==except&&seatsOverlap(position,p)))return position;
  }
 }
 return null;
}
/** A local, editable proposal. It never writes agents, invokes AI, or publishes. */
export function organizationSuggestion(agents:Agent[]):Json{
 const groups=new Map<string,Agent[]>();
 for(const agent of agents.filter(a=>a.enabled!==false)){
  const department=agent.department?.trim()||'待分配部门';
  const existing=[...groups.keys()].find(name=>name.toLowerCase()===department.toLowerCase())||department;
  groups.set(existing,[...(groups.get(existing)||[]),agent]);
 }
 if(groups.size>10)throw Error('目前最多支持 10 个部门楼层；请先整理部门，不能静默合并或遗漏成员。');
 const floors:Json[]=[],positions:Record<string,Json>={};
 for(const[department,members]of groups){
  const floor=suggestedFloor(floors.length+1,department,members.length>18);floors.push(floor);
  for(const member of members){const seat=freeSeat(floor.zones[0],floor.floor,positions);if(!seat)throw Error(`${department} 的成员超过当前楼层可容纳的工位数，请调整组织后重试；未遗漏或移动任何成员。`);positions[member.id]=seat;}
 }
 if(!floors.length)floors.push(suggestedFloor(1,'待分配部门'));
 return {floors,positions,description:'根据现有成员部门生成的一层一部门建议；未填写部门的成员暂列“待分配部门”，请人工确认。'};
}
/** Advisory counterpart of publication validation; the backend is authoritative. */
export function organizationProblem(value:Json,agents:Agent[]=[]):string{
 const floors:Json[]=value.floors||[],positions:Record<string,Json>=value.positions||{};
 if(!floors.length)return '';
 if(floors.length>10)return '最多支持 10 个部门楼层。';
 const numbers=new Set<number>(),departments=new Set<string>(),ids=new Set<string>();
 for(const f of floors){
  if(!Number.isInteger(f.floor)||f.floor<1||f.floor>10||numbers.has(f.floor))return '楼层编号必须为 1–10 且不能重复。';numbers.add(f.floor);
  const department=String(f.department||'');if(!String(f.name||'').trim()||!department.trim()||department!==department.trim())return '请填写楼层名称与无首尾空白的部门名称。';
  if(departments.has(department.toLowerCase()))return '默认一层一个部门，同一部门不能重复占用多个楼层。';departments.add(department.toLowerCase());
  if(!f.zones.some((z:Json)=>z.kind==='work'))return '每个楼层至少需要一个工作区。';
  for(const z of f.zones){
   if(!/^[a-zA-Z][a-zA-Z0-9_-]{0,47}$/.test(z.id||'')||ids.has(z.id))return '区域标识需全局唯一，以字母开头，仅含字母、数字、下划线或短横线。';ids.add(z.id);
   if(!String(z.name||'').trim()||!zoneKinds[z.kind])return '请填写区域名称并选择有效的区域类型。';
   if(!['x','z','width','depth'].every(k=>Number.isFinite(z[k]))||z.width<=0||z.depth<=0||Math.abs(z.x)+z.width/2>12+1e-9||Math.abs(z.z)+z.depth/2>8+1e-9)return '区域边界必须位于 X ±12、Z ±8 的楼层范围内。';
   if(z.color&&!/^#[0-9a-fA-F]{6}$/.test(z.color))return '区域颜色需要 #RRGGBB 格式。';
  }
  if(f.zones.some((z:Json,i:number)=>f.zones.slice(i+1).some((b:Json)=>Math.abs(z.x-b.x)<(z.width+b.width)/2-1e-9&&Math.abs(z.z-b.z)<(z.depth+b.depth)/2-1e-9)))return '同一楼层的区域不能重叠。';
 }
 const entries=Object.entries(positions);
 for(const[id,p]of entries){
  if(agents.length&&!agents.some(a=>a.id===id&&a.enabled!==false))return '布局包含不存在或停用的成员，请从草稿移除。';
  const f=floors.find(f=>f.floor===p.floor),zone=f?.zones.find((z:Json)=>z.id===p.zone&&z.kind==='work');
  if(!zone)return '成员必须选择所在楼层的有效工作区域。';
  if(!Number.isFinite(p.x)||!Number.isFinite(p.z)||!zoneContains(zone,p.x,p.z))return '完整桌椅必须位于工作区域内，请调整工位或区域边界。';
 }
 if(entries.some(([,a],i)=>entries.slice(i+1).some(([,b])=>seatsOverlap(a,b))))return '同层桌椅不能重叠，请拉开工位间距。';
 return '';
}

export function OfficeEditor({value,onChange,agents,readOnly,organization=false}:{value:Json;onChange:(c:Json)=>void;agents:Agent[];readOnly:boolean;organization?:boolean}){
 const[floor,setFloor]=useState(1),[selected,setSelected]=useState(''),[message,setMessage]=useState(''),[addId,setAddId]=useState('');
 const positions:Record<string,Json>=value.positions||{},definitions:Json[]=organization?(value.floors||[]):[];
 const managed=definitions.length>0;
 const floors=managed?definitions.map(f=>f.floor).sort((a,b)=>a-b):Array.from(new Set([1,2,...Object.values(positions).map(p=>p.floor||1)])).sort((a,b)=>a-b);
 const activeFloor=floors.includes(floor)?floor:floors[0]||1,definition=definitions.find(f=>f.floor===activeFloor);
 const selectedId=positions[selected]?selected:Object.keys(positions)[0],position=positions[selectedId];
 const assignedFloor=definitions.find(f=>f.floor===position?.floor);
 const selectedAgent=agents.find(a=>a.id===selectedId);
 const problem=managed?organizationProblem(value,agents):'';
 const write=(patch:Json)=>{if(readOnly)return;onChange({...value,...patch});setMessage('');};
 const set=(id:string,patch:Json)=>write({positions:{...positions,[id]:{...positions[id],...patch}}});
 const changeFloor=(patch:Json)=>write({floors:definitions.map(f=>f.floor===activeFloor?{...f,...patch}:f)});
 const changeZone=(id:string,patch:Json)=>changeFloor({zones:definition.zones.map((z:Json)=>z.id===id?{...z,...patch}:z)});
 const assign=(id:string,targetFloor:number,zoneId?:string)=>{
  if(readOnly)return;
  const f=definitions.find(f=>f.floor===targetFloor),zones=f?.zones.filter((z:Json)=>z.kind==='work'&&(!zoneId||z.id===zoneId))||[];
  for(const zone of zones){const seat=freeSeat(zone,targetFloor,positions,id);if(seat){set(id,seat);setSelected(id);setFloor(targetFloor);setAddId('');return;}}
  setMessage('目标楼层没有可容纳完整桌椅的空工位。请先调整工作区或成员位置。');
 };
 const unplaced=agents.filter(a=>a.enabled!==false&&!positions[a.id]);
 const departmentChanges=managed?Object.entries(positions).filter(([id,p])=>agents.find(a=>a.id===id)?.department!==(definitions.find(f=>f.floor===p.floor)?.department||'')):[];
 return <section className="office-designer organization-designer" data-testid={organization?'organization-editor':'office-position-editor'}>
  <header><div><h3>{organization?'组织与办公室设计':'办公室布局设计'}</h3><p>{organization?'默认一层一个部门，区域与成员工位来自同一份版本化配置。':'拖动成员安排工位；位置按团队模板版本保存。'}</p></div><select aria-label="办公室楼层" value={activeFloor} onChange={e=>setFloor(Number(e.target.value))}>{floors.map(f=><option key={f} value={f}>{f} 楼{definitions.find(d=>d.floor===f)?.department?' · '+definitions.find(d=>d.floor===f)?.department:''}</option>)}</select></header>
  {organization&&<><div className="organization-actions"><button type="button" className="button secondary small" disabled={readOnly} onClick={()=>{try{const proposal=organizationSuggestion(agents);write(proposal);setFloor(proposal.floors[0].floor);setMessage('已生成待确认建议，仅修改当前草稿；没有变更真实成员。');}catch(e){setMessage((e as Error).message);}}}>按现有部门生成一层一部门建议</button><button type="button" className="button secondary small" disabled={readOnly||definitions.length>=10} onClick={()=>{const next=Array.from({length:10},(_,i)=>i+1).find(n=>!definitions.some(f=>f.floor===n));if(!next)return;write({floors:[...definitions,suggestedFloor(next,'新部门 '+next)]});setFloor(next);}}>增加部门楼层</button></div>{!managed&&<p className="callout">当前为兼容布局，仅保存工位坐标，不改变部门。生成部门建议会替换当前编辑草稿中的位置，请重新核对；不会自动应用。</p>}
   {definition&&<><fieldset disabled={readOnly} className="organization-floor-fields"><Field label="楼层名称"><input aria-label="组织楼层名称" maxLength={80} value={definition.name||''} onChange={e=>changeFloor({name:e.target.value})}/></Field><Field label="所属部门"><input aria-label="楼层所属部门" maxLength={80} value={definition.department||''} onChange={e=>changeFloor({department:e.target.value})}/></Field><button type="button" className="text-button danger-text" disabled={Object.values(positions).some(p=>p.floor===activeFloor)} onClick={()=>{write({floors:definitions.filter(f=>f.floor!==activeFloor)});setFloor(floors.find(f=>f!==activeFloor)||1);}}>移除空楼层</button></fieldset><p className="microcopy">移除楼层前请先迁移或从布局移除该层工位；不会删除 Agent。</p></>}
  </>}
  {(message||problem)&&<p role={problem?'alert':'status'} className={problem?'form-error':'callout'}>{message}{message&&problem?' ':''}{problem}{problem?' 草稿仍可保存，修正后才能发布。':''}</p>}
  <div className={'office-floor '+(managed?'organization-floor':'')} role="region" aria-label={'办公室 '+activeFloor+' 楼布局'} onDragOver={e=>{if(!readOnly)e.preventDefault();}} onDrop={e=>{
   e.preventDefault();if(readOnly)return;const id=e.dataTransfer.getData('text/plain');if(!positions[id])return;
   const r=e.currentTarget.getBoundingClientRect(),x=Math.round(((e.clientX-r.left)/r.width*24-12)*2)/2,z=Math.round(((e.clientY-r.top)/r.height*16-8)*2)/2;
   const zone=definition?.zones.find((zone:Json)=>zone.kind==='work'&&zoneContains(zone,x,z)),candidate={x,z,floor:activeFloor,zone:zone?.id||positions[id].zone};
   if(managed&&(!zone||Object.entries(positions).some(([other,p])=>other!==id&&seatsOverlap(candidate,p)))){setMessage('请将完整桌椅放入无重叠的工作区，不能跨越墙面、会议区或其他工位。');return;}
   set(id,candidate);setSelected(id);
  }}><span className="office-floor-label">F{activeFloor} · {definition?.department||'COLLABORATION FLOOR'}</span>
   {definition?.zones.map((z:Json)=><div key={z.id} className={'organization-zone '+z.kind} data-zone-id={z.id} style={{left:(z.x-z.width/2+12)/24*100+'%',top:(z.z-z.depth/2+8)/16*100+'%',width:z.width/24*100+'%',height:z.depth/16*100+'%','--zone-color':z.color||'#83a184'}}><b>{z.name}</b><small>{zoneKinds[z.kind]}</small></div>)}
   {Object.entries(positions).filter(([,p])=>(p.floor||1)===activeFloor).map(([id,p])=><button key={id} type="button" draggable={!readOnly} onDragStart={e=>e.dataTransfer.setData('text/plain',id)} onClick={()=>setSelected(id)} className={'office-desk '+(selectedId===id?'selected':'')} style={{left:Math.max(0,Math.min(100,(Number(p.x||0)+12)/24*100))+'%',top:Math.max(0,Math.min(100,(Number(p.z||0)+8)/16*100))+'%'}}><Box size={15}/><b>{agents.find(a=>a.id===id)?.name||id.slice(0,8)}</b><small>{definition?.zones.find((z:Json)=>z.id===p.zone)?.name||p.zone||'协作区'}</small></button>)}
  </div>
  {position&&<><div className="office-position-fields"><Field label="工位成员"><select aria-label="工位成员" value={selectedId} onChange={e=>{setSelected(e.target.value);setFloor(positions[e.target.value].floor||1);}}>{Object.keys(positions).map(id=><option value={id} key={id}>{agents.find(a=>a.id===id)?.name||id}</option>)}</select></Field><Field label="楼层">{managed?<select aria-label="工位楼层" disabled={readOnly} value={position.floor} onChange={e=>assign(selectedId,Number(e.target.value))}>{definitions.map(f=><option key={f.floor} value={f.floor}>{f.floor} 楼 · {f.department}</option>)}</select>:<input aria-label="工位楼层" disabled={readOnly} min={1} max={10} type="number" value={position.floor||1} onChange={e=>set(selectedId,{floor:Number(e.target.value)})}/>}</Field><Field label="X 坐标"><input aria-label="工位 X 坐标" disabled={readOnly} type="number" step="any" min={-12} max={12} value={position.x??0} onChange={e=>set(selectedId,{x:Number(e.target.value)})}/></Field><Field label="Z 坐标"><input aria-label="工位 Z 坐标" disabled={readOnly} type="number" step="any" min={-8} max={8} value={position.z??0} onChange={e=>set(selectedId,{z:Number(e.target.value)})}/></Field><Field label="办公区域">{managed?<select aria-label="工位工作区域" disabled={readOnly} value={position.zone||''} onChange={e=>assign(selectedId,position.floor,e.target.value)}><option value="">选择本层工作区</option>{assignedFloor?.zones.filter((z:Json)=>z.kind==='work').map((z:Json)=><option key={z.id} value={z.id}>{z.name}</option>)}</select>:<input aria-label="工位区域名称" disabled={readOnly} value={position.zone||''} onChange={e=>set(selectedId,{zone:e.target.value})}/>}</Field></div>{organization&&<div className="organization-member-impact"><span>{selectedAgent?.name||selectedId}：{selectedAgent?.department||'未分配部门'} → {assignedFloor?.department||'部门保持不变'} · 仅在应用后生效</span><button type="button" className="text-button danger-text" disabled={readOnly} onClick={()=>{const next={...positions};delete next[selectedId];write({positions:next});setSelected('');}}>从布局移除工位</button></div>}</>}
  {organization&&managed&&<><div className="organization-member-add"><select aria-label="添加现有成员工位" disabled={readOnly||!unplaced.length} value={addId} onChange={e=>setAddId(e.target.value)}><option value="">选择尚未安排的成员</option>{unplaced.map(a=><option key={a.id} value={a.id}>{a.name} · {a.department||'未分配部门'}</option>)}</select><button type="button" className="button secondary small" disabled={readOnly||!addId} onClick={()=>assign(addId,activeFloor)}>安排到当前楼层</button></div>
   {definition&&<section className="organization-zone-editor" aria-label="楼层区域编辑"><header><h4>区域划分 · {definition.department}</h4><button type="button" className="button secondary small" disabled={readOnly||definition.zones.length>=20} onClick={()=>changeFloor({zones:[...definition.zones,{id:'zone_'+requestId().slice(0,8),name:'新工作区',kind:'work',x:0,z:0,width:4,depth:4,color:'#83a184'}]})}>增加区域</button></header><p className="microcopy">坐标为区域中心。新增区域需手动调整到空闲空间；允许边界接触，不允许区域或桌椅重叠。</p>{definition.zones.map((zone:Json)=><fieldset key={zone.id} disabled={readOnly} className="organization-zone-fields"><Field label="区域名称"><input aria-label={'区域名称 '+zone.id} maxLength={80} value={zone.name} onChange={e=>changeZone(zone.id,{name:e.target.value})}/></Field><Field label="区域类型"><select aria-label={'区域类型 '+zone.id} value={zone.kind} onChange={e=>changeZone(zone.id,{kind:e.target.value})}>{Object.entries(zoneKinds).map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></Field>{[['x','中心 X',-12,12],['z','中心 Z',-8,8],['width','宽度',.1,24],['depth','深度',.1,16]].map(([key,label,min,max])=><Field key={String(key)} label={String(label)}><input aria-label={label+' '+zone.id} type="number" step="any" min={Number(min)} max={Number(max)} value={zone[String(key)]} onChange={e=>changeZone(zone.id,{[String(key)]:Number(e.target.value)})}/></Field>)}<Field label="区域颜色"><input aria-label={'区域颜色 '+zone.id} type="color" value={zone.color||'#83a184'} onChange={e=>changeZone(zone.id,{color:e.target.value})}/></Field><button type="button" className="text-button danger-text" aria-label={'移除区域 '+zone.id} disabled={Object.values(positions).some(p=>p.floor===activeFloor&&p.zone===zone.id)} onClick={()=>changeFloor({zones:definition.zones.filter((z:Json)=>z.id!==zone.id)})}>移除空区域</button><small className="organization-zone-id">标识：{zone.id}</small></fieldset>)}</section>}
   <section className="organization-impact" aria-label="组织应用影响"><h4>应用影响 · 等待人工确认</h4><p>{definitions.length} 个部门楼层，{Object.keys(positions).length} 个工位，{departmentChanges.length} 位成员的部门将调整。未列入此布局的成员保持原配置；从布局移除工位不删除 Agent。</p>{departmentChanges.length>0&&<ul>{departmentChanges.map(([id,p])=><li key={id}>{agents.find(a=>a.id===id)?.name||id}：{agents.find(a=>a.id===id)?.department||'未分配部门'} → {definitions.find(f=>f.floor===p.floor)?.department}</li>)}</ul>}<p>不改变模型绑定、工具权限、Skill、汇报关系或通信策略。部门调整会改变后续运行中“同部门”通信的成员范围；已创建的任务保留冻结版本。</p></section>
  </>}
 </section>;
}

function BenchmarkEditor({value,onChange}:{value:Json;onChange:(c:Json)=>void}){const cases:Json[]=value.cases||[];const patch=(i:number,p:Json)=>onChange({cases:cases.map((c,j)=>j===i?{...c,...p}:c)});return <section className="benchmark-editor"><p className="design-context">使用真实业务样例评估代码与推理。模型回复按明确预期核验；仅以文本或 JSON 匹配评分，不执行生成的代码。</p>{cases.map((c,i)=><article key={i}><header><b>案例 {i+1}</b><button className="text-button danger-text" type="button" onClick={()=>onChange({cases:cases.filter((_,j)=>j!==i)})}>移除</button></header><div className="form-grid"><Field label="案例标识"><input required value={c.id||''} onChange={e=>patch(i,{id:e.target.value})}/></Field><Field label="评分维度"><select value={c.dimension||'reasoning'} onChange={e=>patch(i,{dimension:e.target.value})}><option value="reasoning">推理能力</option><option value="coding">代码能力</option></select></Field></div><Field label="测试提示"><textarea required rows={3} value={c.prompt||''} onChange={e=>patch(i,{prompt:e.target.value})}/></Field><Field label="预期答案"><textarea required rows={2} value={typeof c.expected==='object'?JSON.stringify(c.expected):c.expected||''} onChange={e=>patch(i,{expected:e.target.value})}/></Field><Field label="匹配规则"><select value={c.match||'exact'} onChange={e=>patch(i,{match:e.target.value})}><option value="exact">去除首尾空白后完全一致</option><option value="contains">包含预期答案</option><option value="json">解析 JSON 后比较</option></select></Field></article>)}<button type="button" className="button secondary" onClick={()=>onChange({cases:[...cases,{id:'case_'+requestId().slice(0,8),dimension:'reasoning',prompt:'',expected:'',match:'exact'}]})}>＋ 添加评测案例</button></section>;}
